changeSet.sql:
CREATE INDEX TFPM_ADDR_ENRICH.IX_FEEDBACK_COUNTRY_FIELD
    ON TFPM_ADDR_ENRICH.VALIDATION_FEEDBACK
    (COUNTRY_HINT, FIELD_NAME, CORRECTED_AT) LOCAL;

CREATE INDEX TFPM_ADDR_ENRICH.IX_FEEDBACK_RESULT
    ON TFPM_ADDR_ENRICH.VALIDATION_FEEDBACK (RESULT_ID) LOCAL;

-- Reviewer queue: pending samples ordered by date
CREATE INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_PENDING
    ON TFPM_ADDR_ENRICH.ACCURACY_SAMPLES (STATUS, COUNTRY_HINT, SAMPLED_AT) LOCAL;

-- Reporting: reviewed samples per country over time
CREATE INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_REVIEWED
    ON TFPM_ADDR_ENRICH.ACCURACY_SAMPLES (COUNTRY_HINT, REVIEWED_AT, STATUS) LOCAL;

CREATE INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_RESULT
    ON TFPM_ADDR_ENRICH.ACCURACY_SAMPLES (RESULT_ID) LOCAL;

rollback.sql:
DROP INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_RESULT;
DROP INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_REVIEWED;
DROP INDEX TFPM_ADDR_ENRICH.IX_SAMPLE_PENDING;

changeSet.sql:
COMMENT ON TABLE TFPM_ADDR_ENRICH.VALIDATION_FEEDBACK IS
    'Operator overrides from maker/checker UI. Cheapest production accuracy proxy.';
COMMENT ON TABLE TFPM_ADDR_ENRICH.ACCURACY_SAMPLES IS
    'Stratified daily samples queued for human review. Source of real per-country production accuracy estimates.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.ACCURACY_SAMPLES.CONFIDENCE_BUCKET IS
    'HIGH (>=0.9), MID (0.7-0.9), LOW (<0.7). Sampled in 4:4:2 ratio per country per day.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.ACCURACY_SAMPLES.PER_FIELD_VERDICT IS
    'JSON: { "FIELD_NAME": { "verdict": "correct|wrong|partial", "should_be": "..." } }';
